2	// lancets, porches, the balcony, and the slab ramps with their landings. Each plot's openings are cut by the vocab
3	// helpers where they cover the element; the rest (single doors, panes, ramps, the granary dock) are written here.
4	// Writes go into air only (the shell leaves every opening empty), so a refused cell is a shell or roof conflict.
5	import { B, shutter } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
6	import {
7	  doorPair, hoistBeam, lancet, louvre, porchDeep, porchWrap, balcony, ventSlot,
8	} from "../vocab.mjs";
9	
10	// Glass panes in one wall plane. Every pane joins its neighbours and the wall beside the window, so each run reads as a
11	// window: `along` is the axis the wall runs along ("x" for a north or south wall, "z" for an east or west wall).
12	function win(g, xs, ys, zs, along = "x") {
13	  const [ka, kb] = along === "x" ? ["east", "west"] : ["south", "north"];
14	  for (const x of xs) for (const y of ys) for (const z of zs) {
15	    const st = { north: "false", east: "false", south: "false", west: "false" };
16	    st[ka] = "true";
17	    st[kb] = "true";
18	    g.set(x, y, z, "minecraft:glass_pane", st);
19	  }
20	}
21	
22	// Folded board leaves: open trapdoors in the column x, y0..y1, one cell in front of the wall (z) and lying flat on it.
23	// The shell owns the wall plane there (jambs, boards, plinth), so the leaves stand clear of it.
24	function leaf(g, x, y0, y1, z, facing) {
25	  for (let y = y0; y <= y1; y++) g.set(x, y, z, ...B.trapdoor("spruce", facing, "bottom", true));
26	}
27	
28	// One single door, both halves, hinge as given, the same facing on both.
29	function door(g, x, y, z, facing, mat, hinge = "left") {
30	  g.set(x, y, z, ...B.door(mat, facing, "lower", hinge));
31	  g.set(x, y + 1, z, ...B.door(mat, facing, "upper", hinge));
32	}
33	
34	// A double door, no transom: two leaves side by side along the wall (x for north/south, z for east/west).
35	function doorDouble(g, x, y, z, facing, mat, along = "x") {
36	  const [dx, dz] = along === "x" ? [1, 0] : [0, 1];
37	  door(g, x, y, z, facing, mat, "left");
38	  door(g, x + dx, y, z + dz, facing, mat, "right");
39	}
40	
41	// The way in: bottom slabs on the ramp row (z), width cells along the front, then the full-block landing (z+1..z+2).
42	// A porch deck that already serves as the landing is passed as landing: null.
43	function ramp(g, x0, width, z, slab, landing) {
44	  for (let i = 0; i < width; i++) g.set(x0 + i, 1, z, ...B.slab(slab, "bottom"));
45	  if (!landing) return;
46	  for (let i = 0; i < width; i++) for (const dz of [1, 2]) g.set(x0 + i, 1, z + dz, `minecraft:${landing}`, {});
47	}
48	
49	export function build(g) {
50	  // ---- Plot 0: cotton gin (front north, wagon bay and loft at z9) ----
51	  // Wagon bay: the shell cut the 4-wide clear door (x 4..7, y 1..4) and built its jambs and birch lintel course (y 5).
52	  // The folded board leaves stand in front of the wall (z 8). The hay door (x 5..6, y 7..8) gets its leaves the same way.
53	  for (const x of [2, 3, 8, 9]) leaf(g, x, 1, 4, 8, "north");
54	  for (const x of [4, 7]) leaf(g, x, 7, 8, 8, "north");
55	  hoistBeam(g, 6, 10, 7, { len: 3 });
56	  louvre(g, 5, 12, 9, "north", 2);
57	  // Side windows (x 1 and x 10) and the back of the gin.
58	  win(g, [1], [2, 3], [11], "z");
59	  win(g, [10], [2, 3], [11], "z");
60	  win(g, [1, 10], [8], [11, 14], "z");
61	  doorPair(g, 5, 1, 16, "south", "spruce_door");
62	  win(g, [3, 8], [2, 3], [16], "x");
63	
64	  // ---- Plot 1: schoolhouse (front north) ----
65	  doorPair(g, 17, 2, 9, "north", "mangrove_door");
66	  win(g, [15, 20], [3, 4], [10], "z");
67	  win(g, [17, 18], [9, 10], [12], "x");
68	  win(g, [13, 22], [3, 4, 5], [13, 15], "z");
69	  // Outer shutters only: z 12 and z 16 beside the two tall windows on each side; the wall between stays plain.
70	  for (const [x, face] of [[12, "west"], [23, "east"]]) {
71	    shutter(g, [x, 3, 12], face, "spruce", { height: 3 });
72	    shutter(g, [x, 3, 16], face, "spruce", { height: 3 });
73	  }
74	  win(g, [17, 18], [5], [17], "x");
75	  ramp(g, 17, 2, 6, "stone_brick", "stone_bricks");
76	
77	  // ---- Plot 2: hill farmhouse (front north, body z 10, deep porch z 7..9) ----
78	  door(g, 29, 2, 10, "north", "dark_oak", "left");
79	  win(g, [30], [2, 3], [10], "x");
80	  win(g, [26, 27, 32, 33], [3, 4], [10], "x");
81	  for (const x of [25, 28, 31, 34]) shutter(g, [x, 3, 9], "north", "mangrove", { height: 2 });
