86	  door(g, 31, 2, 14, "south", "dark_oak", "left");
87	  door(g, 26, 2, 16, "west", "dark_oak", "left");
88	  win(g, [29, 30], [3, 4], [17], "x");
89	  louvre(g, 29, 11, 14, "south", 2);
90	  ramp(g, 29, 2, 6, "mangrove", null);
91	
92	  // ---- Plot 3: blacksmith (open forge front, shuttered west opening) ----
93	  shutter(g, [36, 2, 11], "west", "spruce", { height: 2 });
94	  shutter(g, [36, 2, 13], "west", "spruce", { height: 2 });
95	
96	  // ---- Plot 4: church (front north, nave z 9..17) ----
97	  doorPair(g, 52, 2, 9, "north", "spruce_door");
98	  for (const x of [51, 52, 53, 54]) g.set(x, 5, 9, ...B.stairs("stone_brick", "south", "top"));
99	  win(g, [52, 53], [11, 12], [9], "x");
100	  for (const z of [11, 13, 15]) {
101	    lancet(g, 49, z, 3, 6, { into: "east", material: "stone_brick" });
102	    lancet(g, 56, z, 3, 6, { into: "west", material: "stone_brick" });
