104	    g.set(49, 3, z, ...B.slab("stone_brick", "top"));
105	    g.set(56, 3, z, ...B.slab("stone_brick", "top"));
106	  }
107	  win(g, [52, 53], [9, 10], [17], "x");
108	  // Belfry openings: louvres in the lower course of each face (the belfry itself is the tower's, P2).
109	  louvre(g, 52, 16, 9, "north", 2);
110	  louvre(g, 52, 16, 12, "south", 2);
111	  louvre(g, 51, 16, 10, "west", 2);
112	  louvre(g, 54, 16, 10, "east", 2);
113	  ramp(g, 52, 3, 6, "stone_brick", "stone_bricks");
114	
115	  // ---- Plot 5: tobacco barn (front north, tall boards) ----
116	  door(g, 65, 1, 9, "north", "spruce", "left");
117	  door(g, 66, 1, 9, "north", "spruce", "right");
118	  g.set(65, 4, 9, "minecraft:stripped_spruce_log", { axis: "x" });
119	  g.set(66, 4, 9, "minecraft:stripped_spruce_log", { axis: "x" });
120	  louvre(g, 65, 12, 9, "north", 2);
121	  louvre(g, 65, 12, 15, "south", 2);
